WITH cleaned AS (SELECT id, session_id, event_time, duration_sec, CAST(duration_sec AS DOUBLE) AS duration_sec_str, COALESCE(page, 'UNKNOWN') AS page_filled FROM web_events WHERE event_time >= TIMESTAMP '2023-09-13 20:00:00' AND event_type = 'add_to_cart'), with_gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) > INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_burst FROM cleaned), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT session_id, CASE WHEN duration_sec_str >= 70 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_str_tier, DATE_TRUNC('MONTH', event_time) AS activity_month, MIN(session_no) AS min_session_no, PERCENTILE_APPROX(duration_sec_str, ARRAY(0.25, 0.5, 0.75)) AS duration_sec_str_quartiles, MIN(session_no) AS min_session_no_2 FROM islands GROUP BY GROUPING SETS ((session_id, CASE WHEN duration_sec_str >= 70 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('MONTH', event_time)), (session_id, CASE WHEN duration_sec_str >= 70 THEN 'PREMIUM' ELSE 'STANDARD' END)) ORDER BY duration_sec_str_tier;
